      out.write("\n");
      out.write("<script>\n");
      out.write("const MAX_WORDS = 120;\n");
      out.write("\n");
      out.write("function countWords(str) {\n");
      out.write("    if (!str) return 0;\n");
      out.write("    const trimmed = str.trim();\n");
      out.write("    if (!trimmed) return 0;\n");
      out.write("    return trimmed.split(/\\s+/).length;\n");
      out.write("}\n");
      out.write("\n");
      out.write("function onContentChange() {\n");
      out.write("    const text = document.getElementById('questionContent').value;\n");
      out.write("    const words = countWords(text);\n");
      out.write("    const numSpan = document.getElementById('wordCountNum');\n");
      out.write("    const badge = document.getElementById('wordCountBadge');\n");
      out.write("    const alertBox = document.getElementById('wordCountAlert');\n");
      out.write("\n");
      out.write("    if (numSpan) numSpan.textContent = words;\n");
      out.write("\n");
      out.write("    if (words > MAX_WORDS) {\n");
      out.write("        badge.classList.remove('bg-slate-100', 'text-slate-700', 'border-slate-200');\n");
      out.write("        badge.classList.add('bg-rose-50', 'text-rose-700', 'border-rose-300');\n");
      out.write("        alertBox.classList.remove('hidden');\n");
      out.write("    } else {\n");
      out.write("        badge.classList.add('bg-slate-100', 'text-slate-700', 'border-slate-200');\n");
      out.write("        badge.classList.remove('bg-rose-50', 'text-rose-700', 'border-rose-300');\n");
      out.write("        alertBox.classList.add('hidden');\n");
      out.write("    }\n");
      out.write("\n");
      out.write("    verifyQuestion();\n");
      out.write("}\n");
      out.write("\n");
      out.write("function getCurrentType() {\n");
      out.write("    const selectedRadio = document.querySelector('input[name=\"type\"]:checked');\n");
      out.write("    return selectedRadio ? selectedRadio.value : 'single_choice';\n");
      out.write("}\n");
      out.write("\n");
      out.write("function onTypeChanged(type) {\n");
      out.write("    const choiceBox = document.getElementById('choiceOptionsBox');\n");
      out.write("    const fillBlankBox = document.getElementById('fillBlankBox');\n");
      out.write("\n");
      out.write("    if (type === 'fill_in_blank') {\n");
      out.write("        choiceBox.classList.add('hidden');\n");
      out.write("        fillBlankBox.classList.remove('hidden');\n");
      out.write("\n");
      out.write("        // Disable inputs inside choice box so they are not submitted\n");
      out.write("        choiceBox.querySelectorAll('input').forEach(input => input.disabled = true);\n");
      out.write("        fillBlankBox.querySelectorAll('input').forEach(input => input.disabled = false);\n");
      out.write("    } else {\n");
      out.write("        choiceBox.classList.remove('hidden');\n");
      out.write("        fillBlankBox.classList.add('hidden');\n");
      out.write("\n");
      out.write("        choiceBox.querySelectorAll('input').forEach(input => input.disabled = false);\n");
      out.write("        fillBlankBox.querySelectorAll('input').forEach(input => input.disabled = true);\n");
      out.write("\n");
      out.write("        // Update radio vs checkbox\n");
      out.write("        const wantedInputType = (type === 'single_choice') ? 'radio' : 'checkbox';\n");
      out.write("        document.querySelectorAll('#choiceRows .correct-box').forEach(box => {\n");
      out.write("            box.type = wantedInputType;\n");
      out.write("        });\n");
      out.write("        renumberChoices();\n");
      out.write("    }\n");
      out.write("\n");
      out.write("    verifyQuestion();\n");
      out.write("}\n");
      out.write("\n");
      out.write("function filterModulesByCourse(selectedCourseId) {\n");
      out.write("    const moduleSelect = document.getElementById('moduleSelect');\n");
      out.write("    if (!moduleSelect) return;\n");
      out.write("\n");
      out.write("    let hasVisible = false;\n");
      out.write("    for (let i = 0; i < moduleSelect.options.length; i++) {\n");
      out.write("        const opt = moduleSelect.options[i];\n");
      out.write("        if (!opt.value) continue;\n");
      out.write("        const optCourse = opt.getAttribute('data-course');\n");
      out.write("        if (!selectedCourseId || !optCourse || optCourse === selectedCourseId) {\n");
      out.write("            opt.style.display = '';\n");
      out.write("            hasVisible = true;\n");
      out.write("        } else {\n");
      out.write("            opt.style.display = 'none';\n");
      out.write("        }\n");
      out.write("    }\n");
      out.write("    verifyQuestion();\n");
      out.write("}\n");
      out.write("\n");
      out.write("function renumberChoices() {\n");
      out.write("    document.querySelectorAll('#choiceRows .choice-row').forEach((row, idx) => {\n");
      out.write("        const box = row.querySelector('.correct-box');\n");
      out.write("        if (box) box.value = idx;\n");
      out.write("    });\n");
      out.write("}\n");
      out.write("\n");
      out.write("function addOptionRow() {\n");
      out.write("    const rowsContainer = document.getElementById('choiceRows');\n");
      out.write("    const index = rowsContainer.querySelectorAll('.choice-row').length;\n");
      out.write("    const type = getCurrentType();\n");
      out.write("    const inputType = (type === 'single_choice') ? 'radio' : 'checkbox';\n");
      out.write("\n");
      out.write("    const row = document.createElement('div');\n");
      out.write("    row.className = 'choice-row flex items-center gap-3 p-2.5 rounded-xl border border-slate-200 bg-slate-50/50';\n");
      out.write("    row.innerHTML = `\n");
      out.write("        <input type=\"hidden\" name=\"optionId\" value=\"\">\n");
      out.write("        <div class=\"flex items-center justify-center w-8\">\n");
      out.write("            <input type=\"");
      out.write((java.lang.String) org.apache.jasper.runtime.PageContextImpl.proprietaryEvaluate("${inputType}", java.lang.String.class, (jakarta.servlet.jsp.PageContext)_jspx_page_context, null));
      out.write("\" name=\"correctIndex\" value=\"");
      out.write((java.lang.String) org.apache.jasper.runtime.PageContextImpl.proprietaryEvaluate("${index}", java.lang.String.class, (jakarta.servlet.jsp.PageContext)_jspx_page_context, null));
      out.write("\" class=\"correct-box w-4 h-4 accent-emerald-600 cursor-pointer\">\n");
      out.write("        </div>\n");
      out.write("        <input type=\"text\" name=\"optionText\" required placeholder=\"Nội dung phương án...\"\n");
      out.write("               class=\"flex-1 px-4 py-2.5 rounded-xl bg-white border border-slate-200 text-xs outline-none focus:ring-2 focus:ring-emerald-500\">\n");
      out.write("        <button type=\"button\" onclick=\"removeOptionRow(this)\"\n");
      out.write("                class=\"w-9 h-9 rounded-xl text-slate-400 hover:text-rose-600 hover:bg-rose-50 flex items-center justify-center transition\">\n");
      out.write("            <i class=\"fa-solid fa-trash-can text-xs\"></i>\n");
      out.write("        </button>\n");
      out.write("    `;\n");
      out.write("    rowsContainer.appendChild(row);\n");
      out.write("    renumberChoices();\n");
      out.write("    verifyQuestion();\n");
      out.write("}\n");
      out.write("\n");
      out.write("function removeOptionRow(btn) {\n");
      out.write("    const row = btn.closest('.choice-row');\n");
      out.write("    if (row) row.remove();\n");
      out.write("    renumberChoices();\n");
      out.write("    verifyQuestion();\n");
      out.write("}\n");
      out.write("\n");
      out.write("function addKeywordRow() {\n");
      out.write("    const container = document.getElementById('keywordRows');\n");
      out.write("    const count = container.querySelectorAll('.keyword-row').length + 1;\n");
      out.write("    const row = document.createElement('div');\n");
      out.write("    row.className = 'keyword-row flex items-center gap-3 p-2.5 rounded-xl border border-purple-200 bg-purple-50/20';\n");
      out.write("    row.innerHTML = `\n");
      out.write("        <input type=\"hidden\" name=\"optionId\" value=\"\">\n");
      out.write("        <span class=\"w-8 text-center text-xs font-bold text-purple-700\">#");
      out.write((java.lang.String) org.apache.jasper.runtime.PageContextImpl.proprietaryEvaluate("${count}", java.lang.String.class, (jakarta.servlet.jsp.PageContext)_jspx_page_context, null));
      out.write("</span>\n");
      out.write("        <input type=\"text\" name=\"optionText\" required placeholder=\"Từ khóa đáp án bổ sung...\"\n");
      out.write("               class=\"flex-1 px-4 py-2.5 rounded-xl bg-white border border-slate-200 text-xs font-semibold text-slate-800 outline-none focus:ring-2 focus:ring-purple-500\">\n");
      out.write("        <button type=\"button\" onclick=\"removeKeywordRow(this)\"\n");
      out.write("                class=\"w-9 h-9 rounded-xl text-slate-400 hover:text-rose-600 hover:bg-rose-50 flex items-center justify-center transition\">\n");
      out.write("            <i class=\"fa-solid fa-trash-can text-xs\"></i>\n");
      out.write("        </button>\n");
      out.write("    `;\n");
      out.write("    container.appendChild(row);\n");
      out.write("    verifyQuestion();\n");
      out.write("}\n");
      out.write("\n");
      out.write("function removeKeywordRow(btn) {\n");
      out.write("    const row = btn.closest('.keyword-row');\n");
      out.write("    if (row) row.remove();\n");
      out.write("    // Renumber badges\n");
      out.write("    document.querySelectorAll('#keywordRows .keyword-row').forEach((r, idx) => {\n");
      out.write("        const badge = r.querySelector('span');\n");
      out.write("        if (badge) badge.textContent = '#' + (idx + 1);\n");
      out.write("    });\n");
      out.write("    verifyQuestion();\n");
      out.write("}\n");
      out.write("\n");
      out.write("function setCheckStatus(elemId, isValid) {\n");
      out.write("    const el = document.getElementById(elemId);\n");
      out.write("    if (!el) return;\n");
      out.write("    const icon = el.querySelector('i');\n");
      out.write("    if (isValid) {\n");
      out.write("        icon.className = 'fa-solid fa-circle-check text-emerald-600';\n");
      out.write("    } else {\n");
      out.write("        icon.className = 'fa-solid fa-circle-xmark text-rose-500';\n");
      out.write("    }\n");
      out.write("}\n");
      out.write("\n");
      out.write("function verifyQuestion() {\n");
      out.write("    const content = (document.getElementById('questionContent').value || '').trim();\n");
      out.write("    const words = countWords(content);\n");
      out.write("    const moduleId = (document.getElementById('moduleSelect').value || '').trim();\n");
      out.write("    const type = getCurrentType();\n");
      out.write("\n");
      out.write("    const isContentValid = content.length > 0;\n");
      out.write("    const isWordsValid = words > 0 && words <= MAX_WORDS;\n");
      out.write("    const isModuleValid = moduleId.length > 0;\n");
      out.write("\n");
      out.write("    let isAnswersValid = false;\n");
      out.write("    if (type === 'fill_in_blank') {\n");
      out.write("        const keywords = Array.from(document.querySelectorAll('#keywordRows input[name=\"optionText\"]'))\n");
      out.write("            .filter(input => !input.disabled && input.value.trim().length > 0);\n");
      out.write("        isAnswersValid = keywords.length >= 1;\n");
      out.write("    } else {\n");
      out.write("        const options = Array.from(document.querySelectorAll('#choiceRows .choice-row input[name=\"optionText\"]'))\n");
      out.write("            .filter(input => !input.disabled && input.value.trim().length > 0);\n");
      out.write("        const correctBoxes = Array.from(document.querySelectorAll('#choiceRows .correct-box:checked'))\n");
      out.write("            .filter(box => !box.disabled);\n");
      out.write("\n");
      out.write("        if (type === 'single_choice') {\n");
      out.write("            isAnswersValid = options.length >= 2 && correctBoxes.length === 1;\n");
      out.write("        } else {\n");
      out.write("            isAnswersValid = options.length >= 2 && correctBoxes.length >= 1;\n");
      out.write("        }\n");
      out.write("    }\n");
      out.write("\n");
      out.write("    setCheckStatus('chkContent', isContentValid);\n");
      out.write("    setCheckStatus('chkWords', isWordsValid);\n");
      out.write("    setCheckStatus('chkModule', isModuleValid);\n");
      out.write("    setCheckStatus('chkAnswers', isAnswersValid);\n");
      out.write("\n");
      out.write("    return isContentValid && isWordsValid && isModuleValid && isAnswersValid;\n");
      out.write("}\n");
